mapper.select:
SELECT * FROM service_credential
WHERE credential_id = #{credentialId}
  AND delete_flag = 0

SELECT * FROM service_credential
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delete_flag = 0

SELECT * FROM service_credential
WHERE tenant_id = #{tenantId}
  AND service_code = #{serviceCode}
  AND delete_flag = 0
ORDER BY id DESC

mapper.update:
UPDATE service_credential
SET delete_flag = id, deleted_at = #{deletedAt}, deleted_by = #{deletedBy}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delete_flag = 0

UPDATE service_credential
SET status = #{status},

        rotated_at = #{rotatedAt},

    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delete_flag = 0

UPDATE service_credential
SET expires_at = #{expiresAt},
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delete_flag = 0
